// La IA extrae datos; el código decide si son suficientes para consultar stock.
const mensaje = $('Entrada de mensaje').first().json;
const raw = $input.first().json;
let texto = raw.output?.flatMap(x => x.content || []).find(x => typeof x.text === 'string')?.text || raw.output_text || '';
texto = texto.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let datos = {};
try { datos = JSON.parse(texto); } catch { /* Se pide aclaración; no se inventan datos. */ }
const producto = typeof datos.producto === 'string' ? datos.producto.trim().slice(0, 120) : '';
const presupuesto = typeof datos.presupuesto === 'number' && Number.isFinite(datos.presupuesto) ? datos.presupuesto : 0;
const moneda = String(datos.moneda || 'BOB').toUpperCase();
const buscar = datos.intencion === 'buscar' && producto.length > 0 && presupuesto > 0 && presupuesto <= 1000000 && ['BOB', 'BS'].includes(moneda);
let respuesta = 'Hola. Escribe la marca o modelo y tu presupuesto máximo en bolivianos en un solo mensaje. Ejemplo: «Busco un Honor X8, tengo 1200 Bs». También puedes escribir «asesor».';
if (!mensaje.texto) respuesta = 'Por ahora atiendo consultas por texto. Escribe la marca o modelo y tu presupuesto en Bs en un solo mensaje.';
else if (datos.intencion === 'asesor') respuesta = 'Entendido. Para atención personal, contacta directamente con la tienda. Este asistente todavía no tiene una derivación a un vendedor configurada.';
else if (!['BOB', 'BS'].includes(moneda)) respuesta = 'El inventario está en bolivianos. Envíame la marca o modelo y tu presupuesto en Bs en un solo mensaje.';
else if (datos.intencion === 'buscar' && !buscar) respuesta = 'Para buscar necesito la marca o modelo y un presupuesto mayor que cero. Envíalos juntos, por ejemplo: «Samsung A15, máximo 1500 Bs».';
return [{json: {...mensaje, cliente: mensaje.cliente || 'Cliente', producto, presupuesto,
  fecha: new Date().toISOString(), id_consulta: `${mensaje.canal}:${mensaje.id_mensaje}`,
  buscar, respuesta_final: respuesta, estado: buscar ? 'pendiente' : 'requiere_datos'}}];

// =====================================================
// 1. PRODUCTOS QUE LLEGAN DESDE GOOGLE SHEETS
// =====================================================

const productosSheets = $input.all().map(item => item.json);


// =====================================================
// 2. CONSULTA DEL CLIENTE DESDE "Editar campos"
// =====================================================

const solicitud = $('SolicitudCliente').first().json;

const cliente = String(
  solicitud.cliente ?? ''
).trim();

const productoBuscado = String(
  solicitud.producto ?? ''
)
  .trim()
  .toLowerCase();

const presupuesto = Number(
  solicitud.presupuesto ?? 0
);


// =====================================================
// 3. NORMALIZAR INVENTARIO
// =====================================================

const inventario = productosSheets.map(producto => ({
  identificacion:
    producto['IDENTIFICACIÓN'] ??
    producto.ID ??
    null,

  marca: String(
    producto.Marca ?? ''
  ).trim(),

  modelo: String(
    producto.Modelo ?? ''
  ).trim(),

  precio: Number(
    producto.Precio ?? 0
  ),

  existencias: Number(
    producto.Stock ?? producto.Existencias ?? 0
  )
}));


// =====================================================
// 4. PRODUCTOS VENDIBLES
// =====================================================

const disponibles = inventario.filter(producto =>
  producto.precio > 0 &&
  producto.precio <= presupuesto &&
  producto.existencias > 0
);


// =====================================================
// 5. PRODUCTOS QUE COINCIDEN CON LO BUSCADO
// =====================================================

const coincidencias = disponibles
  .filter(producto => {

    const marca =
      producto.marca.toLowerCase();

    const modelo =
      producto.modelo.toLowerCase();

    return (
      `${marca} ${modelo}`.includes(productoBuscado)
    );

  })
  .sort((a, b) => b.precio - a.precio);


// =====================================================
// 6. ALTERNATIVAS
// =====================================================

const alternativas = disponibles
  .filter(producto => {

    const marca =
      producto.marca.toLowerCase();

    const modelo =
      producto.modelo.toLowerCase();

    const coincide =
      `${marca} ${modelo}`.includes(productoBuscado);

    return !coincide;

  })
  .sort((a, b) => b.precio - a.precio);


// =====================================================
// 7. LIMITAR RESULTADOS
// =====================================================

const productosEncontrados =
  coincidencias.slice(0, 3);

const productosAlternativos =
  alternativas.slice(0, 3);


// =====================================================
// 8. DETERMINAR ESTADO
// =====================================================

let estado;

if (productosEncontrados.length > 0) {

  estado = 'encontrado';

} else if (productosAlternativos.length > 0) {

  estado = 'solo_alternativas';

} else {

  estado = 'sin_resultados';

}


// =====================================================
// 9. SALIDA
// =====================================================

return [
  {
    json: {
      cliente,
      producto_buscado: productoBuscado,
      presupuesto,
      estado,

      cantidad_encontrada:
        productosEncontrados.length,

      productos:
        productosEncontrados,

      cantidad_alternativas:
        productosAlternativos.length,

      alternativas:
        productosAlternativos
    }
  }
];
